import{_ as s,l as n,o as e,c as o,v as i,p as l,x as t,d as p,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"混合策略与存在性","description":"","frontmatter":{"title":"混合策略与存在性","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mixed-strategy.md","filePath":"econ/mixed-strategy.md","lastUpdated":1789023840000}'),h={name:"econ/mixed-strategy.md"};function E(_,a,c,u,A,B){const r=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=i('<h1 id="混合策略与存在性" tabindex="-1">混合策略与存在性 <a class="header-anchor" href="#混合策略与存在性" aria-label="Permalink to &quot;混合策略与存在性&quot;">​</a></h1><div class="epigraph"><p>每个有限策略式博弈至少有一个混合策略均衡点。</p><footer>—— Nash, Equilibrium Points in n-Person Games, PNAS, 1950</footer></div><p><a href="/econ/nash-equilibrium">上一课</a>（策略式与纳什）。在此之上，解写成相互最优反应，并指出纯策略可以空。猜硬币、点球左右、监察与偷税，最优反应是「别让对方猜中」，任何纯招都被针对。缺口是存在性：给有限博弈一个一定非空的均衡集，并把混合解释成对手必须无差异。本课钉这一点，不进入扩展式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有限集 \\(S_i\\) 上的纯策略，最优反应对应在边界上跳动，乘积对应可以没有不动点。混合策略 \\(\\sigma_i\\in\\Delta(S_i)\\) 把行动空间做成单纯形，期望效用</p> \\[u_i(\\sigma)=\\sum_{s\\in S}\\Bigl(\\prod_j\\sigma_j(s_j)\\Bigr)u_i(s) \\]<p>对 \\(\\sigma_i\\) 线性。最优反应变成「把概率只放在纯策略最佳应答上」，对应凸值、上半连续。角谷给出不动点：这就是纳什存在定理。</p><p>混合不是「喜欢随机」。均衡里，被混合的那些纯策略必须给出相同的期望支付，否则应把概率全部挪到更好的那一个。随机化的功能是让对手无差异，从而对手也愿意随机。</p><h3 id="存在不是唯一-混合不是可观测的行动" tabindex="-1">存在不是唯一，混合不是可观测的行动 <a class="header-anchor" href="#存在不是唯一-混合不是可观测的行动" aria-label="Permalink to &quot;存在不是唯一，混合不是可观测的行动&quot;">​</a></h3><p>存在定理不挑哪一个均衡，也不说局中人真的掷骰子。等价解释：群体里不同人抽到不同纯策略，宏观频率等于 \\(\\sigma\\)。实验里能否把混合读成频率，是后话；定义仍是 \\(\\Delta(S_i)\\) 上的纳什。</p><p><span class="marginnote">两人零和有限博弈，von Neumann 的极小极大值等于混合纳什支付。Nash 把存在性从零和推广到一般 \\(n\\) 人。证明骨架与<a href="/econ/ge-existence">竞争均衡存在性</a>同属角谷，定义域是策略单纯形的乘积。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>有限博弈：每个 \\(S_i\\) 有限。混合策略空间 \\(\\Sigma=\\prod_i\\Delta(S_i)\\) 是紧凸集。最优反应对应 \\(r:\\Sigma\\rightrightarrows\\Sigma\\) 非空、凸值、上半连续，故存在 \\(\\sigma^*\\in r(\\sigma^*)\\)。</p><p>检查混合纳什的操作：对每一 \\(i\\)，支撑集 \\(\\mathrm{supp}(\\sigma_i^*)\\) 里每个纯策略都是对 \\(\\sigma_{-i}^*\\) 的最佳应答，支撑外的纯策略不更好。这比「对所有混合偏离都不亏」更便于手算。</p><p>连续行动（古诺产量）可以在纯策略上存在，靠的是拟凹与紧凸，不必混合。本课的存在性针对有限行动；两种技术不要混成一句「博弈都有均衡」。</p>',15)),(e(),l(m,null,{default:t(()=>[d(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20PURE%5B%22%E7%BA%AF%E7%AD%96%E7%95%A5%EF%BC%9A%E5%AF%B9%E5%BA%94%E5%8F%AF%E7%A9%BA%22%5D%20--%3E%20MIX%5B%22%CF%83%20%E2%88%88%20%CE%94(S)%22%5D%0A%20%20MIX%20--%3E%20KAK%5B%22%E8%A7%92%E8%B0%B7%EF%BC%9A%E6%9C%80%E4%BC%98%E5%8F%8D%E5%BA%94%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A%20%20KAK%20--%3E%20EX%5B%22%E6%9C%89%E9%99%90%E5%8D%9A%E5%BC%88%E5%9D%87%E8%A1%A1%E9%9D%9E%E7%A9%BA%22%5D%0A%20%20EX%20--%3E%20IND%5B%22%E6%B7%B7%E5%90%88%E6%94%AF%E6%92%91%E5%86%85%E5%BF%85%E9%A1%BB%E6%97%A0%E5%B7%AE%E5%BC%82%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么无差异是关键：若对手的混合还让某一纯策略严格更好，自己应退回纯策略，均衡瓦解。故巡逻必须以使小偷在偷与不偷之间无差异的概率进行——不是因为警察喜欢掷硬币，而是因为只有无差异才能让小偷也停在混合里。支付差决定混合概率，概率本身往往不是目标。</p><p>这与<a href="/econ/expected-utility">期望效用</a>课序衔接：策略式里的 \\(u_i\\) 已经是 vNM 效用，混合上的线性来自独立性。若放弃独立性，混合均衡的含义要重写，主干不走。存在性本身也不挑均衡：猜硬币的两个纯策略各 1/2 是唯一混合纳什，但协调博弈可以有两个纯和一个混合，混合往往风险更差，本课不把它当选择规则。</p><h3 id="检查支撑的操作" tabindex="-1">检查支撑的操作 <a class="header-anchor" href="#检查支撑的操作" aria-label="Permalink to &quot;检查支撑的操作&quot;">​</a></h3><p>猜一个支撑，令支撑内各纯策略对对手混合的支付相等，解出概率，再验证支撑外确实不更好。支付差变了，均衡频率立刻变——比较静态落在概率上，不落在「喜欢随机」上。二人零和里，混合纳什支付等于极小极大值，有「博弈的值」；非零和没有值这个对象。相关均衡允许公共信号协调，集合更大；主干仍用独立混合。</p><p><span class="marginnote">纯化（Harsanyi 1973）：把混合读成对微扰私有支付的纯策略极限。个体不必掷骰子，群体频率仍可以是 \\(\\sigma^*\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>无限（可数）纯策略集，均衡可以空。不连续支付（伯川德加整数定价的某些写法）也会空。存在性不给选择：多个混合均衡时，哪一个被玩，要靠精炼或制度。扩展式里，混合可以在信息集上，也可以在行为策略上，Kuhn 定理在完美回忆下把两者接通——下一课要用到树，不在本课展开。</p><p>行为策略与混合策略的区分要等到有信息集的树；本课策略式里两者还不必分开。</p><p>后课默认：有限策略式均衡集非空；谈到随机化，先检查无差异条件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>纯策略纳什可空；混合把行动做成单纯形，角谷给出存在。</li><li>均衡混合要求支撑内纯策略无差异。</li><li>随机化是为了让对手无差异，不是偏好随机。</li><li>连续行动另靠拟凹，不自动等于混合。</li><li>出处：Nash, <em>PNAS</em> 1950；von Neumann, 1928 极小极大。</li></ul>',12))])}const S=s(h,[["render",E]]);export{f as __pageData,S as default};
